"""This class handles RESTful API web service requests for the Santana Platform"""
import json
import os
import requests

class PlatformRESTRequests:
    """
    Class to manage REST API web service requests based on the Santana
    Design Specification for the Santana Platform as documented here:
    https://docs.elektaplatform.com/package-group/content-product-elements

    Attributes
    ---------

    response_format: str
        Response format for the REST API requests

    Methods
    ---------

    read_json_file(json_file)
        Reads a JSON config file and returns a dictionary of config data
        used for authorisation tokens and other API requests

    generate_auth_token(auth_data_file)
        Generates an authorisation bearer token from the credentials
        provided by the auth_data_file. Access token is required to
        enable clients to call protected web APIs

    auto_verify_patient(auth_token, patient_data_file)
        Automatically verifies the patient using the auth_token,
        patient ID and treatment session ID from the
        patient_data_file.

    auto_verify_accessory(auth_token, accessory_data_file)
        Automatically verifies an accessory using the auth_token,
        accessory code and treatment session ID from the
        accessory_data_file.

    tsm_external_adapter_verify_patient(auth_token, patient_data_file)
        Emulates an external client to verify the patient using the
        auth_token and patient ID from the patient_data_file.

    tsm_external_adapter_verify_accessory(auth_token, accessory_data_file)
        Emulates an external client to verify an accessory using the
        auth_token and accessory code from the accessory_data_file.

    """

    def __init__(self, response_format: str="json") -> None:
        self.format = response_format


    def read_json_file(self, json_file: str='platform_data_config.json') -> dict:
        """
        Reads a JSON file containing config data to be used in REST requests
        on the Santana platform and returns the data as a dictionary.

        Args:
            json_file (str): Name of the JSON file containing config data

        Returns:
            data_dict (dict): Dictionary of data to be used in REST URL endpoints
        """

        default_interops_path = "elekta-testing-automation/interops/libraries/rest_requests/"
        data_file = os.path.join(default_interops_path, json_file)

        with open(data_file, 'r') as json_file_obj:
            data_dict = json.load(json_file_obj)
            return data_dict


    def generate_auth_token(self, auth_data_file: str='platform_data_config.json') -> str:
        """
        Generates an authorisation bearer token based on the credentials from the
        JSON auth_data_file. The authorisation token is typically used in the header
        of the REST requests to allow clients to securely call protected web APIs.

        Args:
            auth_data_file (str): Name of the JSON file containing config data

        Returns:
            access_token (str): The authorisation bearer token as a string
        """

        # Obtain authorisation data and credentials from json config file
        auth_dict = self.read_json_file(json_file=auth_data_file)
        base_url = auth_dict.get("target_base_url")
        auth_cid = auth_dict.get("auth_client_id")
        auth_usrname = auth_dict.get("auth_username")
        auth_pword = auth_dict.get("auth_password")

        payload = {
            "client_id": auth_cid,
            "scope": "openid email profile",
            "grant_type": "password",
            "username": auth_usrname,
            "password": auth_pword
            }

        response = requests.post(f"{base_url}/iam/realms/elekta/protocol/openid-connect/token",
                             data=payload,
                             verify=False)

        # Check response is OK
        if response.status_code == 200:
            if self.format == "json":
                access_token = response.json()["access_token"]
                return access_token


    def auto_verify_patient(self, auth_token: str, patient_data_file: str='platform_data_config.json') -> bool:
        """
        Automatically verify the patient using the access token, patient ID and
        treatment session ID from the JSON patient_data_file.

        Args:
            auth_token (str): Authorisation bearer token
            patient_data_file (str): Name of the JSON file containing config data

        Returns:
            (bool): True on success, False on failure
        """

        headers = { "Authorization": f"Bearer {auth_token}" }

        # Need to set an empty body for the payload, otherwise a 415 unsupported
        # media type error is returned
        payload = {}

        # Obtain patient verification data from json config file
        patient_verify_dict = self.read_json_file(json_file=patient_data_file)
        base_url = patient_verify_dict.get("target_base_url")
        patient_id = patient_verify_dict.get("patient_id")
        treatment_session_id = patient_verify_dict.get("treatment_session_id")

        response = requests.put(f"{base_url}/elekta-emla-setup-control-patient-verification/V1/patient/{patient_id}/{treatment_session_id}/auto-verify",
                                headers=headers,
                                json=payload,
                                verify=False)

        # Check response is OK
        if response.status_code == 200:
            return True
        else:
            return False


    def auto_verify_accessory(self, auth_token: str, accessory_data_file: str='platform_data_config.json') -> bool:
        """
        Automatically verify an accessory using the access token, accessory code and
        treatment session ID from the JSON accessory_data_file.

        Args:
            auth_token (str): Authorisation bearer token
            accessory_data_file (str): Name of the JSON file containing config data

        Returns:
            (bool): True on success, False on failure
        """

        headers = { "Authorization": f"Bearer {auth_token}" }

        # Obtain accessory verification data from json config file
        accessory_verify_dict = self.read_json_file(json_file=accessory_data_file)
        base_url = accessory_verify_dict.get("target_base_url")
        accessory_code = accessory_verify_dict.get("accessory_code")
        treatment_session_id = accessory_verify_dict.get("treatment_session_id")

        response = requests.put(f"{base_url}/elekta-emla-accessory-control-accessories/v2/accessory/{treatment_session_id}/{accessory_code}/auto-verify",
                                headers=headers,
                                verify=False)

        # Check response is OK
        if response.status_code == 200:
            return True
        else:
            return False


    def tsm_external_adapter_verify_patient(self, auth_token: str, patient_data_file: str='platform_data_config.json') -> bool:
        """
        Simulates patient verification from an external client/system using the
        access token and patient ID from the JSON patient_data_file.

        Args:
            auth_token (str): Authorisation bearer token
            patient_data_file (str): Name of the JSON file containing config data

        Returns:
            (bool): True on success, False on failure
        """

        headers = {
            "Authorization": f"Bearer {auth_token}",
            "Content-Type": "application/json"
            }

        # Obtain patient verification data from json config file
        patient_verify_dict = self.read_json_file(json_file=patient_data_file)
        base_url = patient_verify_dict.get("target_base_url")
        patient_id = patient_verify_dict.get("patient_id")
        patient_name = patient_verify_dict.get("patient_name")

        payload = {
            "PatientId": patient_id,
            "PatientName": patient_name,
            "IsVerified": False
            }

        response = requests.put(f"{base_url}/elekta-emla-tsm-external-adapter/v1/patient/{patient_id}/verify",
                                headers=headers,
                                #data=payload,
                                json=payload,
                                verify=False)

        # Check response is OK
        if response.status_code == 200:
            return True
        else:
            return False


    def tsm_external_adapter_verify_accessory(self, auth_token: str, accessory_data_file: str='platform_data_config.json') -> bool:
        """
        Simulates accessory verification from an external client/system using the
        access token and accessory code from the JSON accessory_data_file.

        Args:
            auth_token (str): Authorisation bearer token
            accessory_data_file (str): Name of the JSON file containing config data

        Returns:
            (bool): True on success, False on failure
        """

        headers = {
            "Authorization": f"Bearer {auth_token}",
            "Content-Type": "application/json"
            }

        # Obtain accessory verification data from json config file
        accessory_verify_dict = self.read_json_file(json_file=accessory_data_file)
        base_url = accessory_verify_dict.get("target_base_url")
        accessory_code = accessory_verify_dict.get("accessory_code")

        response = requests.put(f"{base_url}/elekta-emla-tsm-external-adapter/v1/accessory/{accessory_code}/verify",
                                headers=headers,
                                verify=False)

        # Check response is OK
        if response.status_code == 200:
            return True
        else:
            return False